290	export async function formatDocumentWithSelectedProvider(
291		accessor: ServicesAccessor,
292		editorOrModel: ITextModel | IActiveCodeEditor,
293		mode: FormattingMode,
294		progress: IProgress<DocumentFormattingEditProvider>,
295		token: CancellationToken,
296		userGesture?: boolean
297	): Promise<void> {
298	
299		const instaService = accessor.get(IInstantiationService);
300		const languageFeaturesService = accessor.get(ILanguageFeaturesService);
301		const model = isCodeEditor(editorOrModel) ? editorOrModel.getModel() : editorOrModel;
302		const provider = getRealAndSyntheticDocumentFormattersOrdered(languageFeaturesService.documentFormattingEditProvider, languageFeaturesService.documentRangeFormattingEditProvider, model);
303		const selected = await FormattingConflicts.select(provider, model, mode, FormattingKind.File);
304		if (selected) {
305			progress.report(selected);
306			await instaService.invokeFunction(formatDocumentWithProvider, selected, editorOrModel, mode, token, userGesture);
307		}
308	}
309	
310	export async function formatDocumentWithProvider(
311		accessor: ServicesAccessor,
312		provider: DocumentFormattingEditProvider,
313		editorOrModel: ITextModel | IActiveCodeEditor,
314		mode: FormattingMode,
315		token: CancellationToken,
316		userGesture?: boolean
317	): Promise<boolean> {
318		const workerService = accessor.get(IEditorWorkerService);
319		const accessibilitySignalService = accessor.get(IAccessibilitySignalService);
320	
321		let model: ITextModel;
322		let cts: CancellationTokenSource;
323		if (isCodeEditor(editorOrModel)) {
324			model = editorOrModel.getModel();
325			cts = new EditorStateCancellationTokenSource(editorOrModel, CodeEditorStateFlag.Value | CodeEditorStateFlag.Position, undefined, token);
326		} else {
327			model = editorOrModel;
328			cts = new TextModelCancellationTokenSource(editorOrModel, token);
329		}
330	
331		let edits: TextEdit[] | undefined;
332		try {
333			const rawEdits = await provider.provideDocumentFormattingEdits(
334				model,
335				model.getFormattingOptions(),
336				cts.token
337			);
338	
339			edits = await workerService.computeMoreMinimalEdits(model.uri, rawEdits);
340	
341			if (cts.token.isCancellationRequested) {
342				return true;
343			}
344	
345		} finally {
346			cts.dispose();
347		}
348	
349		if (!edits || edits.length === 0) {
350			return false;
351		}
352	
353		if (isCodeEditor(editorOrModel)) {
354			// use editor to apply edits
355			FormattingEdit.execute(editorOrModel, edits, mode !== FormattingMode.Silent);
356	
357			if (mode !== FormattingMode.Silent) {
358				editorOrModel.revealPositionInCenterIfOutsideViewport(editorOrModel.getPosition(), ScrollType.Immediate);
359			}
