orderedGroups(model: ITextModel): T[][] {
	const result: T[][] = [];
	let lastBucket: T[];
	let lastBucketScore: number;

	this._orderedForEach(model, false, entry => {
		if (lastBucket && lastBucketScore === entry._score) {
